/// The comment at the top of every file bdd_flutter rewrites on each build.
///
/// [source] says what the file is generated from, e.g. `cart.feature`.
String generatedHeader(String source) {
  return '// GENERATED CODE - DO NOT MODIFY BY HAND.\n'
      '// Generated by bdd_flutter from $source.\n'
      '// Run `dart run bdd_flutter build` after changing a .feature file.\n\n';
}
